"""License key model for platform-generated activation keys."""

from sqlalchemy import Boolean, Column, DateTime, ForeignKey, Integer, String
from sqlalchemy.orm import relationship

from app.database import Base
from app.models.base import BaseModelMixin


class LicenseKey(Base, BaseModelMixin):
    """A license key generated by the platform admin and redeemed by a pharmacy.

    Attributes:
        key: Unique activation key string (e.g. PRO-XXXXXXXX-XXXXXXXX-365D)
        plan: Target plan granted by this key (basic / pro / enterprise)
        duration_days: Number of days the license is extended upon redemption
        max_users: Maximum active users allowed after redemption
        pharmacy_id: FK to the pharmacy that redeemed this key (nullable until used)
        used_at: Timestamp when the key was redeemed (nullable until used)
        created_by_id: FK to the platform admin who generated this key
        is_active: Whether this key can still be redeemed (False = revoked or used)
        notes: Optional internal note from the platform admin
    """

    __tablename__ = "license_keys"

    key = Column(String(100), unique=True, nullable=False, index=True)
    plan = Column(String(30), nullable=False, default="basic")
    duration_days = Column(Integer, nullable=False, default=365)
    max_users = Column(Integer, nullable=False, default=3)

    pharmacy_id = Column(Integer, ForeignKey("pharmacies.id"), nullable=True, index=True)
    used_at = Column(DateTime, nullable=True)

    created_by_id = Column(Integer, ForeignKey("users.id"), nullable=True)
    is_active = Column(Boolean, default=True, nullable=False)
    notes = Column(String(500), nullable=True)

    # Relationships
    pharmacy = relationship("Pharmacy", foreign_keys=[pharmacy_id])
    created_by = relationship("User", foreign_keys=[created_by_id])

    def __repr__(self):
        return f"<LicenseKey(id={self.id}, key='{self.key}', plan='{self.plan}', active={self.is_active})>"

